/**
 * Serve team_coverage.json from XDB or public folder.
 * In prod Nest, this would query XDB shard xdb.nest_bellsproutcoverage via Drizzle.
 * For now, read from public/team_coverage.json (generated by tools/team_mapper.py --dry-run).
 */
import { promises as fs } from 'fs';
import path from 'path';

export async function GET() {
  try {
    const filePath = path.join(process.cwd(), 'public', 'team_coverage.json');
    const data = await fs.readFile(filePath, 'utf-8');
    return new Response(data, {
      headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
    });
  } catch (e) {
    return Response.json({ error: 'coverage not found', hint: 'run tools/team_mapper.py --dry-run' }, { status: 404 });
  }
}
